using System.Security.Claims;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;
using Modules.Sales.DTOs;
using Modules.Sales.Entities;
using Modules.Sales.Services;
using Shared.Primitives.Identifiers;

namespace Modules.Sales;

public static class SalesModuleExtensions
{
    public static IServiceCollection AddSalesModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, SalesModuleManifestProvider>();
        services.AddSingleton<Repositories.SalesRepository>();
        services.AddSingleton<SalesService>();
        return services;
    }

    public static WebApplication MapSalesModule(this WebApplication app)
    {
        var group = app.MapGroup("/api/v1/sales").WithTags("Sales").RequireAuthorization().RequireRateLimiting("api");
        group.MapGet("/legal-entities/{entityId:guid}/quotations", async (Guid entityId, string? state, Guid? partyId, int? page, int? pageSize, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.read", entityId, ct), () => service.ListQuotationsAsync(Tenant(http), entityId, state, partyId, page ?? 1, pageSize ?? 50, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations", async (Guid entityId, CreateQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { if (request.LegalEntityId != entityId) return Results.BadRequest(new { code = "sales.entity_mismatch" }); var access = await AccessAsync(http, subjects, authorizer, "sales.quotation.create", entityId, ct); if (access is { Allowed: true } && request.Lines.Any(line => line.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "sales.price_override", entityId, ct)) return Results.Forbid(); return await Execute(http, access, () => service.CreateQuotationAsync(Tenant(http), Actor(http), request, ct), StatusCodes.Status201Created); });
        group.MapGet("/legal-entities/{entityId:guid}/quotations/{id:guid}", async (Guid entityId, Guid id, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.read", entityId, ct), () => service.GetQuotationAsync(Tenant(http), entityId, id, ct)));
        group.MapPut("/legal-entities/{entityId:guid}/quotations/{id:guid}", async (Guid entityId, Guid id, UpdateQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { var access = await AccessAsync(http, subjects, authorizer, "sales.quotation.edit", entityId, ct); if (access is { Allowed: true } && request.Lines.Any(line => line.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "sales.price_override", entityId, ct)) return Results.Forbid(); return await Execute(http, access, () => service.UpdateQuotationAsync(Tenant(http), Actor(http), id, entityId, request, ct)); });
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/open", async (Guid entityId, Guid id, TransitionQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.open", entityId, ct), () => service.OpenQuotationAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/accept", async (Guid entityId, Guid id, AcceptQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.acceptance.record", entityId, ct), () => service.AcceptQuotationAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/decline", async (Guid entityId, Guid id, TransitionQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.decline", entityId, ct), () => service.DeclineQuotationAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/cancel", async (Guid entityId, Guid id, TransitionQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.cancel", entityId, ct), () => service.CancelQuotationAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/revise", async (Guid entityId, Guid id, UpdateQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.revise", entityId, ct), () => service.ReviseQuotationAsync(Tenant(http), Actor(http), entityId, id, request.Version, request.Lines, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/convert-to-invoice", async (Guid entityId, Guid id, ConvertQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.convert_invoice", entityId, ct), () => service.ConvertQuotationAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/accept-and-invoice", async (Guid entityId, Guid id, AcceptAndInvoiceQuotationRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { var access = await AccessAsync(http, subjects, authorizer, "sales.acceptance.record", entityId, ct); if (access is { Allowed: true } && !await HasPermissionAsync(http, subjects, authorizer, "sales.quotation.convert_invoice", entityId, ct)) return Results.Forbid(); return await Execute(http, access, () => service.AcceptAndInvoiceAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, ct)); });
        group.MapPost("/legal-entities/{entityId:guid}/quotations/{id:guid}/convert-to-order", async (Guid entityId, Guid id, ConvertQuotationToOrderRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.quotation.convert_order", entityId, ct), () => service.ConvertQuotationToOrderAsync(Tenant(http), Actor(http), entityId, id, request, ct), StatusCodes.Status201Created));
        group.MapGet("/legal-entities/{entityId:guid}/orders", async (Guid entityId, int? page, int? pageSize, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.read", entityId, ct), () => service.ListOrdersAsync(Tenant(http), entityId, page ?? 1, pageSize ?? 50, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/orders", async (Guid entityId, CreateOrderRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { if (request.LegalEntityId != entityId) return Results.BadRequest(new { code = "sales.entity_mismatch" }); var access = await AccessAsync(http, subjects, authorizer, "sales.order.create", entityId, ct); if (access is { Allowed: true } && request.Lines.Any(line => line.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "sales.price_override", entityId, ct)) return Results.Forbid(); return await Execute(http, access, () => service.CreateOrderAsync(Tenant(http), Actor(http), request, ct), StatusCodes.Status201Created); });
        group.MapGet("/legal-entities/{entityId:guid}/orders/{id:guid}", async (Guid entityId, Guid id, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.read", entityId, ct), () => service.GetOrderAsync(Tenant(http), entityId, id, ct)));
        group.MapPut("/legal-entities/{entityId:guid}/orders/{id:guid}", async (Guid entityId, Guid id, UpdateOrderRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { var access = await AccessAsync(http, subjects, authorizer, "sales.order.edit", entityId, ct); if (access is { Allowed: true } && request.Lines.Any(line => line.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "sales.price_override", entityId, ct)) return Results.Forbid(); return await Execute(http, access, () => service.AmendOrderAsync(Tenant(http), Actor(http), entityId, id, request, ct)); });
        group.MapPost("/legal-entities/{entityId:guid}/orders/{id:guid}/confirm", async (Guid entityId, Guid id, OrderCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { var access = await AccessAsync(http, subjects, authorizer, "sales.order.confirm", entityId, ct); var overrideAllowed = request.CreditOverrideReason is not null && await HasPermissionAsync(http, subjects, authorizer, "sales.credit_override", entityId, ct); return await Execute(http, access, () => service.ConfirmOrderAsync(Tenant(http), Actor(http), entityId, id, request, overrideAllowed, ct)); });
        group.MapPost("/legal-entities/{entityId:guid}/orders/{id:guid}/release-reservation", async (Guid entityId, Guid id, OrderCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.cancel", entityId, ct), () => service.ReleaseOrderReservationsAsync(Tenant(http), Actor(http), entityId, id, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/orders/{id:guid}/cancel-remaining", async (Guid entityId, Guid id, OrderCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.cancel", entityId, ct), () => service.CancelOrderAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/orders/{id:guid}/fulfill", async (Guid entityId, Guid id, FulfillOrderRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.fulfill", entityId, ct), () => service.FulfillOrderAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/orders/{id:guid}/create-invoice", async (Guid entityId, Guid id, OrderCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.order.invoice", entityId, ct), () => service.ConvertOrderToInvoiceAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/returns", async (Guid entityId, CreateReturnRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { if (request.LegalEntityId != entityId) return Results.BadRequest(new { code = "sales.entity_mismatch" }); return await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.return.create", entityId, ct), () => service.CreateReturnAsync(Tenant(http), Actor(http), request, ct), StatusCodes.Status201Created); });
        group.MapGet("/legal-entities/{entityId:guid}/returns/{id:guid}", async (Guid entityId, Guid id, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.history.read", entityId, ct), () => service.GetReturnAsync(Tenant(http), entityId, id, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/returns/{id:guid}/approve", async (Guid entityId, Guid id, ReturnCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.return.approve", entityId, ct), () => service.ApproveReturnAsync(Tenant(http), Actor(http), entityId, id, request, ct)));
        group.MapPost("/legal-entities/{entityId:guid}/returns/{id:guid}/execute", async (Guid entityId, Guid id, ReturnCommandRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.return.execute", entityId, ct), () => service.ExecuteReturnAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, ct)));
        group.MapPut("/legal-entities/{entityId:guid}/customer-profiles/{partyId:guid}", async (Guid entityId, Guid partyId, SalesCustomerProfileRequest request, HttpContext http, SalesService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "sales.customer_profile.manage", entityId, ct), async () => { await service.SaveCustomerProfileAsync(Tenant(http), Actor(http), request with { PartyId = partyId, LegalEntityId = entityId }, ct); return true; }));
        return app;
    }

    private static async Task<IResult> Execute<T>(HttpContext http, Access? access, Func<Task<T>> action, int status = StatusCodes.Status200OK)
    { if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid(); try { var result = await action(); return status == StatusCodes.Status201Created ? Results.Created(http.Request.Path, result) : Results.Ok(result); } catch (SalesException ex) { var code = ex.Code; var statusCode = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code.Contains("stale", StringComparison.Ordinal) || code.Contains("conflict", StringComparison.Ordinal) || code.Contains("idempotency", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: statusCode, title: ex.Message, extensions: new Dictionary<string, object?> { ["code"] = code }); } }
    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid entity, CancellationToken ct) { if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenant) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membership) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actor)) return null; if (Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var bound) && bound != entity) return new(new(tenant), actor, false, membership); var subject = await subjects.LoadAsync(new TenantId(tenant), membership, ct); return subject is null ? null : new(new TenantId(tenant), actor, authorizer.Authorize(subject, permission, PermissionScope.ForLegalEntity(new TenantId(tenant), new LegalEntityId(entity))), membership); }
    private static TenantId Tenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext http) => Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private static Guid Membership(HttpContext http) => Guid.Parse(http.User.FindFirstValue("membership_id")!);
    private static async Task<bool> HasPermissionAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid entity, CancellationToken ct)
    { if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenant) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membership)) return false; var subject = await subjects.LoadAsync(new TenantId(tenant), membership, ct); return subject is not null && authorizer.Authorize(subject, permission, PermissionScope.ForLegalEntity(new TenantId(tenant), new LegalEntityId(entity))); }
    private sealed record Access(TenantId Tenant, Guid Actor, bool Allowed, Guid MembershipId);
}

